(async()=>{
 let ready=false,saveQueue=Promise.resolve(),view='projects',selected='all',search='',teamFocus='all',trash=false,month=new Date().getMonth(),year=new Date().getFullYear(),calendarMode='month',eventType='all';
 const uid=prefix=>prefix+'-'+crypto.randomUUID();const today=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
 let {members,teams,documents,events}=window.Bootstrap;
 const home=[...$('main').children].filter(e=>e.tagName!=='FOOTER');const page=document.createElement('section');page.id='workspace-page';page.className='hidden';$('main').insertBefore(page,$('footer'));
 const nav=document.querySelector('nav');nav.insertAdjacentHTML('beforeend','<p class="nav-label">ORGANIZATION</p><button data-work="documents">▤ <span>Documents</span></button><button data-work="teams">♧ <span>Teams & members</span></button><button data-work="calendar">▦ <span>Event calendar</span></button>');
 const status=$('#save-status');
 const modal=document.createElement('dialog');modal.id='workspace-editor';modal.setAttribute('aria-labelledby','work-editor-title');document.body.append(modal);let submitAction;
 const options=(items,value,label='name')=>items.map(x=>`<option value="${esc(x.id)}"${x.id===value?' selected':''}>${esc(x[label])}</option>`).join('');
 const projectOptions=id=>'<option value="all">All projects</option>'+options(projects,id);
 const shortDate=d=>new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
 const activeMembers=()=>members.filter(m=>m.active);
 const avatar=m=>m?.avatar?`<img class="member-avatar" src="${m.avatar}" alt="${esc(m.name)}">`:`<span class="member-avatar initials" style="background:${m?.color||'#e9e9ef'}" aria-label="${esc(m?.name||'Unassigned')}">${esc((m?.name||'?').split(' ').map(n=>n[0]).slice(0,2).join(''))}</span>`;
 window.Workspace={persist,avatarByName:name=>avatar(members.find(m=>m.name===name)),memberOptions:name=>{let list=members.filter(m=>m.active||m.name===name);return list.map(m=>`<option${m.name===name?' selected':''}>${esc(m.name)}</option>`).join('')}};
 function snapshot(){return {version:3,projects,issues,notes,milestones,activity,members,teams,documents,events}}
 async function read(store,id){if(store==='files')return ProjectAPI.file(id);throw Error('Unsupported operation');}
 function persist(fileEntry){status.textContent='Saving to database…';let data=structuredClone(snapshot());saveQueue=saveQueue.catch(()=>{}).then(()=>ProjectAPI.save(data,fileEntry));saveQueue.then(()=>{status.textContent='Saved to MySQL'},error=>{status.textContent='Save failed · reload before continuing';toast(error.message)});return saveQueue;}
 ready=true;status.textContent='Connected to MySQL';
 const renderBefore=render;render=function(){renderBefore();updateTeamSummary();};
 function updateTeamSummary(){
  const list=activeMembers();
  const stack=limit=>list.slice(0,limit).map(avatar).join('')+(list.length>limit?`<span class="member-avatar initials" aria-label="${list.length-limit} more members">+${list.length-limit}</span>`:'');
  $('#team-avatars').innerHTML=stack(5);
  $('#toolbar-avatars').innerHTML=stack(3);
  $('#team-member-count').textContent=`${list.length} ${list.length===1?'member':'members'}`;
  $('#manage-team').onclick=()=>open('teams');
  $('.planning-help').textContent='Shared tasks across all views';
 }

 function open(next){view=next;PlanningUI.show('overview');home.forEach(el=>el.classList.add('hidden'));page.classList.remove('hidden');document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('selected',next==='projects'?b.dataset.view==='projects':b.dataset.work===next));$('#crumb').textContent={projects:'Projects',documents:'Documents',teams:'Teams & members',calendar:'Event calendar'}[next];$('#search').closest('.search').classList.add('hidden');draw();if(innerWidth<980)document.body.classList.remove('collapsed');window.scrollTo({top:0,behavior:'instant'})}
 window.addEventListener('planning:navigate',()=>page.classList.add('hidden'));
 document.querySelector('[data-view="projects"]').onclick=()=>open('projects');document.querySelectorAll('[data-work]').forEach(b=>b.onclick=()=>open(b.dataset.work));
 function header(title,desc,actions){return `<div class="work-heading"><div><p class="eyebrow">PROJECT WORKSPACE</p><h1>${title}</h1><p class="muted">${desc}</p></div><div class="work-actions">${actions}</div></div>`}
 function filters(extra=''){return `<div class="work-filters"><label>Project<select id="work-project">${projectOptions(selected)}</select></label><label class="search">⌕ <input id="work-search" aria-label="Search ${view}" placeholder="Search ${view}…" value="${esc(search)}"></label>${extra}</div>`}
 function draw(){if(page.classList.contains('hidden'))return;if(view==='projects')drawProjects();if(view==='documents')drawDocuments();if(view==='teams')drawTeams();if(view==='calendar')drawCalendar()}
 function drawProjects(){let list=projects.filter(p=>(selected==='all'||p.id===selected)&&p.name.toLowerCase().includes(search.toLowerCase()));page.innerHTML=header('Projects','One portfolio. A clear home for every project.','<button class="secondary" data-action="backup">Export backup</button><button class="primary" data-action="new-project">+ New project</button>')+filters()+`<div class="portfolio">${list.map(p=>{let tasks=issues.filter(t=>t.projectId===p.id),team=teams.find(t=>t.id===p.teamId),pm=members.find(m=>m.name===p.manager);return `<article class="panel portfolio-card"><div class="portfolio-top"><span class="project-symbol" style="background:${p.color}">▱</span><span class="badge">${esc(p.status)}</span><button class="text-btn" data-project-edit="${p.id}" aria-label="Edit ${esc(p.name)}">Edit</button></div><small>${p.id}</small><h2>${esc(p.name)}</h2><p>${esc(p.description||'No description yet.')}</p><div class="project-owner">${avatar(pm)}<div>${esc(p.manager)}<small>Project manager</small></div></div><div class="project-team-label">${esc(team?.name||'No team assigned')}</div><div class="member-stack">${(team?.memberIds||[]).map(id=>avatar(members.find(m=>m.id===id))).join('')}</div><div class="portfolio-progress"><span>${tasks.filter(t=>t.status==='Done').length} / ${tasks.length} tasks complete</span><b>${Planning.progress(tasks)}%</b></div><div class="progress-track"><i style="width:${Planning.progress(tasks)}%"></i></div><div class="portfolio-date">${shortDate(p.startDate)} – ${shortDate(p.endDate)}</div><div class="portfolio-links"><button data-project-plan="${p.id}">View tasks</button><button data-project-docs="${p.id}">Documents (${documents.filter(d=>d.projectId===p.id&&!d.trashed).length})</button><button data-project-events="${p.id}">Calendar</button></div></article>`}).join('')||'<p class="empty">No projects match your search.</p>'}</div>`}
 function drawDocuments(){let list=documents.filter(d=>!!d.trashed===trash&&(selected==='all'||d.projectId===selected)&&(d.name+' '+d.category).toLowerCase().includes(search.toLowerCase()));page.innerHTML=header('Project documents','Keep briefs, specifications, and release files with their project.','<button class="primary" data-action="new-doc">+ Add document</button>')+filters(`<button class="secondary" data-action="toggle-trash">${trash?'View documents':'Trash ('+documents.filter(d=>d.trashed).length+')'}</button>`)+`<div class="panel document-table"><div class="document-head"><span>DOCUMENT</span><span>PROJECT</span><span>UPDATED</span><span>ACTIONS</span></div>${list.map(d=>`<article class="document-row"><div class="document-name"><span class="file-symbol">${d.kind==='note'?'≡':'▤'}</span><div><button class="task-title" data-doc-open="${d.id}">${esc(d.name)}</button><small>${esc(d.category)} · ${d.kind==='note'?'Workspace note':formatSize(d.size)}</small></div></div><span>${esc(projects.find(p=>p.id===d.projectId)?.name||'')}</span><time>${shortDate(d.updated.slice(0,10))}</time><div class="row-actions">${trash?`<button data-doc-restore="${d.id}">Restore</button>`:`<button data-doc-edit="${d.id}">Edit</button><button data-doc-download="${d.id}">Download</button><button data-doc-trash="${d.id}" aria-label="Move ${esc(d.name)} to trash">Trash</button>`}</div></article>`).join('')||`<div class="work-empty"><span>▤</span><h2>${trash?'Trash is empty':'A home for your project knowledge'}</h2><p>${trash?'Removed documents can be restored here.':'Upload a file or write a document. Files are stored with this project on the server.'}</p>${trash?'':'<button class="secondary" data-action="new-doc">Add your first document</button>'}</div>`}</div>`}
 function formatSize(n){return n>1048576?(n/1048576).toFixed(1)+' MB':Math.max(1,Math.round(n/1024))+' KB'}
 function drawTeams(){let filtered=members.filter(m=>(teamFocus==='all'||teams.find(t=>t.id===teamFocus)?.memberIds.includes(m.id))&&(m.name+' '+m.role).toLowerCase().includes(search.toLowerCase()));page.innerHTML=header('Teams & members','Give every project a team and every task an owner.','<button class="secondary" data-action="new-member">+ Add member</button><button class="primary" data-action="new-team">+ New team</button>')+`<div class="team-grid">${teams.map(t=>`<article class="panel team-card"><div class="panel-heading"><h2>${esc(t.name)}</h2><button class="text-btn" data-team-edit="${t.id}">Edit team</button></div><p>${esc(t.description||'')}</p><div class="member-stack">${t.memberIds.map(id=>avatar(members.find(m=>m.id===id))).join('')}</div><div class="team-card-foot"><span>${t.memberIds.length} members · ${projects.filter(p=>p.teamId===t.id).length} projects</span><button data-team-focus="${t.id}">View members</button></div></article>`).join('')}</div><div class="directory-heading"><h2>Member directory <span class="count">${members.length}</span></h2><div class="work-filters"><label class="search">⌕ <input id="work-search" placeholder="Find a member…" aria-label="Search teams" value="${esc(search)}"></label><select id="team-filter" aria-label="Filter members by team"><option value="all">All teams</option>${options(teams,teamFocus)}</select></div></div><div class="member-grid">${filtered.map(m=>`<article class="panel member-card">${avatar(m)}<div><h3>${esc(m.name)}</h3><p>${esc(m.role)}</p><small>${esc(m.email||'No email added')}</small><div class="member-tags">${teams.filter(t=>t.memberIds.includes(m.id)).map(t=>`<span>${esc(t.name)}</span>`).join('')}${!m.active?'<span>Inactive</span>':''}</div></div><button class="text-btn" data-member-edit="${m.id}" aria-label="Edit ${esc(m.name)}">Edit</button></article>`).join('')||'<p class="empty">No members match this filter.</p>'}</div><p class="local-note">Team records are shared across the workspace. Adding a member does not send an invitation.</p>`}
 const types=['Release','Meeting','Milestone','Other'];const eventClass=t=>t.toLowerCase();
 function eventList(){return events.filter(e=>!e.cancelled&&(selected==='all'||e.projectId===selected)&&(eventType==='all'||e.type===eventType)&&e.title.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time))}
 function eventChip(e){return `<button class="event-chip ${eventClass(e.type)}" data-event-edit="${e.id}" title="${esc(e.title)}">${e.allDay?'':e.time+' '}${esc(e.title)}</button>`}
 function drawCalendar(){let first=new Date(year,month,1),offset=(first.getDay()+6)%7,start=new Date(year,month,1-offset),days=new Date(year,month+1,0).getDate(),rows=Math.ceil((offset+days)/7),monthName=first.toLocaleDateString('en-US',{month:'long',year:'numeric'}),list=eventList();let dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
 page.innerHTML=header('Event calendar','Releases, meetings, and milestones—planned together.','<button class="primary" data-action="new-event">+ New event</button>')+filters(`<select id="event-type" aria-label="Filter event type"><option value="all">All event types</option>${types.map(t=>`<option${t===eventType?' selected':''}>${t}</option>`).join('')}</select>`)+`<div class="calendar-heading"><div><button class="icon-btn" data-month="-1" aria-label="Previous month">‹</button><h2>${monthName}</h2><button class="icon-btn" data-month="1" aria-label="Next month">›</button><button class="secondary" data-action="today">Today</button></div><div class="plan-tabs"><button data-calendar-mode="month" class="${calendarMode==='month'?'active':''}">Month</button><button data-calendar-mode="agenda" class="${calendarMode==='agenda'?'active':''}">Agenda</button></div></div>`;
 if(calendarMode==='month'){page.innerHTML+=`<div class="panel calendar-scroll"><div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="weekday">${d}</div>`).join('')}${Array.from({length:rows*7},(_,i)=>{let d=new Date(start);d.setDate(start.getDate()+i);let k=dateKey(d),daily=list.filter(e=>e.date<=k&&e.endDate>=k);return `<div class="calendar-day ${d.getMonth()!==month?'outside':''} ${k===today()?'is-today':''}"><button class="day-number" data-event-date="${k}" aria-label="Add event on ${k}">${d.getDate()}</button>${daily.map(eventChip).join('')}</div>`}).join('')}</div></div>`}else{let begin=dateKey(first),end=dateKey(new Date(year,month+1,0)),agenda=list.filter(e=>e.date<=end&&e.endDate>=begin);page.innerHTML+=`<div class="panel agenda">${agenda.map(e=>`<article><div class="agenda-date">${shortDate(e.date)}<small>${e.allDay?'All day':e.time+' – '+e.endTime}</small></div><div><span class="event-label ${eventClass(e.type)}">${e.type}</span><button class="task-title" data-event-edit="${e.id}">${esc(e.title)}</button><p>${esc(projects.find(p=>p.id===e.projectId)?.name||'Workspace')} · ${esc(e.location||'No location')}</p></div><div class="member-stack">${e.attendees.map(id=>avatar(members.find(m=>m.id===id))).join('')}</div></article>`).join('')||'<p class="empty">No events this month. Add a release, meeting, or milestone.</p>'}</div>`}page.innerHTML+=`<div class="calendar-key">${types.map(t=>`<span class="event-label ${eventClass(t)}">${t}</span>`).join('')}<small>Events retain their timezone. No invitations are sent.</small></div>`}
 function field(label,name,value='',type='text',required=true){return `<label for="wm-${name}">${label}</label><input id="wm-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='text'?'maxlength="160"':''}>`}
 function select(label,name,content){return `<label for="wm-${name}">${label}</label><select id="wm-${name}" name="${name}">${content}</select>`}
 function area(label,name,value=''){return `<label for="wm-${name}">${label}</label><textarea id="wm-${name}" name="${name}" rows="4">${esc(value)}</textarea>`}
 function checks(label,name,list,ids){return `<fieldset class="member-checks"><legend>${label}</legend>${list.map(m=>`<label>${avatar(m)}<span>${esc(m.name)}</span><input type="checkbox" name="${name}" value="${m.id}"${ids.includes(m.id)?' checked':''}></label>`).join('')||'<p>Add members first.</p>'}</fieldset>`}
 function editDialog(title,html,action,extra=''){modal.innerHTML=`<form id="workspace-form"><div class="panel-heading"><h2 id="work-editor-title">${title}</h2><button type="button" class="icon-btn" data-close-work aria-label="Close editor">×</button></div><div class="workspace-fields">${html}<p id="workspace-error" role="alert"></p></div><div class="dialog-actions">${extra}<button type="button" class="secondary" data-close-work>Cancel</button><button type="submit" class="primary">Save</button></div></form>`;submitAction=action;modal.showModal();modal.querySelector('input:not([type=checkbox])')?.focus()}
 async function commit(message,file){await persist(file);renderBefore();updateTeamSummary();draw();modal.close();toast(message)}
 function editProject(id){let p=projects.find(p=>p.id===id)||{name:'',description:'',manager:'Bin Li',teamId:teams[0]?.id,status:'Active',startDate:today(),endDate:today(),color:'#aaa0ce'};editDialog(id?'Edit project':'New project',field('Project name','name',p.name)+area('Description','description',p.description)+`<div class="field-grid"><div>${select('Project manager','manager',members.map(m=>`<option${m.name===p.manager?' selected':''}>${esc(m.name)}</option>`).join(''))}</div><div>${select('Team','teamId','<option value="">No team</option>'+options(teams,p.teamId))}</div><div>${field('Start date','startDate',p.startDate,'date')}</div><div>${field('End date','endDate',p.endDate,'date')}</div><div>${select('Status','status',['Active','On hold','Completed','Archived'].map(s=>`<option${s===p.status?' selected':''}>${s}</option>`).join(''))}</div><div>${field('Project color','color',p.color,'color')}</div></div>`,async f=>{let v=Object.fromEntries(f);if(v.endDate<v.startDate)throw Error('End date must be on or after the start date.');if(!v.name.trim())throw Error('Enter a project name.');let m=members.find(m=>m.name===v.manager);Object.assign(v,{name:v.name.trim(),date:shortDate(v.startDate),end:shortDate(v.endDate),initials:(m?.name||'Unassigned').split(' ').map(n=>n[0]).join(''),lead:m?.name||'Unassigned',team:0});if(id)Object.assign(p,v);else projects.push({...v,id:uid('PRJ')});await commit('Project saved')})}
 function editTeam(id){let t=teams.find(t=>t.id===id)||{name:'',description:'',memberIds:[]};editDialog(id?'Edit team':'New team',field('Team name','name',t.name)+area('Description','description',t.description)+checks('Team members','memberIds',members,t.memberIds),async f=>{let v={name:f.get('name').trim(),description:f.get('description'),memberIds:f.getAll('memberIds')};if(!v.name)throw Error('Enter a team name.');if(id)Object.assign(t,v);else teams.push({...v,id:uid('team')});await commit('Team saved')})}
 function fileData(file){return new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Could not read this file.'));r.readAsDataURL(file)})}
 function editMember(id){let m=members.find(m=>m.id===id)||{name:'',role:'',email:'',avatar:'',color:'#e7e2f3',active:true};editDialog(id?'Edit member':'Add member',`<div class="avatar-editor">${avatar(m)}<span>Choose a photo, or use initials.</span></div>`+field('Full name','name',m.name)+field('Role','role',m.role)+field('Email (optional)','email',m.email,'email',false)+`<label for="wm-avatar">Avatar photo (PNG, JPEG or WebP · up to 2 MB)</label><input id="wm-avatar" name="avatar" type="file" accept="image/png,image/jpeg,image/webp"><label class="inline-check"><input type="checkbox" name="removeAvatar"> Use initials instead of photo</label>`+select('Member status','active',`<option value="true"${m.active?' selected':''}>Active</option><option value="false"${!m.active?' selected':''}>Inactive</option>`)+checks('Teams','teamIds',teams,teams.filter(t=>t.memberIds.includes(id)).map(t=>t.id)),async f=>{let name=f.get('name').trim();if(!name)throw Error('Enter a member name.');if(members.some(x=>x.id!==id&&x.name.toLowerCase()===name.toLowerCase()))throw Error('A member with this name already exists.');let photo=f.get('avatar'),image=m.avatar;if(f.has('removeAvatar'))image='';else if(photo.size){if(!['image/png','image/jpeg','image/webp'].includes(photo.type)||photo.size>2097152)throw Error('Choose a PNG, JPEG or WebP image smaller than 2 MB.');image=await fileData(photo)}let old=m.name,v={name,role:f.get('role'),email:f.get('email'),avatar:image,color:m.color,active:f.get('active')==='true'};if(id){Object.assign(m,v);issues.filter(t=>t.assignee===old).forEach(t=>t.assignee=name);projects.forEach(p=>{if(p.manager===old)p.manager=name;if(p.lead===old)p.lead=name})}else{m={...v,id:uid('member')};members.push(m)}let teamIds=f.getAll('teamIds');teams.forEach(t=>{t.memberIds=t.memberIds.filter(x=>x!==m.id);if(teamIds.includes(t.id))t.memberIds.push(m.id)});await commit('Member saved')})}
 function editDoc(id){let d=documents.find(d=>d.id===id)||{name:'',projectId:selected==='all'?projects[0]?.id:selected,category:'Brief',kind:'note',content:''};editDialog(id?'Edit document':'Add document',field('Document title','name',d.name)+select('Project','projectId',options(projects,d.projectId))+select('Category','category',['Brief','Specification','Design','Release','Meeting notes','Other'].map(s=>`<option${s===d.category?' selected':''}>${s}</option>`).join(''))+select('Document type','kind',`<option value="note"${d.kind==='note'?' selected':''}>Written document</option><option value="file"${d.kind==='file'?' selected':''}>Uploaded file</option>`)+`<div id="doc-written">${area('Content','content',d.content||'')}</div><div id="doc-upload"><label for="wm-file">${id?'Replace file (optional)':'Choose file'} · up to 25 MB</label><input id="wm-file" name="file" type="file"><p>${esc(d.fileName||'Files are stored on the server.')}</p></div>`,async f=>{let kind=f.get('kind'),file=f.get('file'),docId=id||uid('doc'),v={id:docId,name:f.get('name').trim(),projectId:f.get('projectId'),category:f.get('category'),kind,content:kind==='note'?f.get('content'):'',updated:new Date().toISOString(),trashed:false};if(!v.name)throw Error('Enter a document title.');if(kind==='file'){if(!file.size&&(!id||d.kind!=='file'))throw Error('Choose a file to upload.');if(file.size>26214400)throw Error('Choose a file smaller than 25 MB.');Object.assign(v,file.size?{size:file.size,fileName:file.name,mime:file.type}:{size:d.size,fileName:d.fileName,mime:d.mime})}if(id)Object.assign(d,v);else documents.push(v);await commit('Document saved',kind==='file'&&file.size?{id:docId,file}:undefined)});let toggle=()=>{let file=$('#wm-kind').value==='file';$('#doc-written').classList.toggle('hidden',file);$('#doc-upload').classList.toggle('hidden',!file)};$('#wm-kind').onchange=toggle;toggle()}
 function editEvent(id,date,defaultType='Meeting'){let e=events.find(e=>e.id===id)||{title:'',type:defaultType,projectId:selected==='all'?projects[0]?.id:selected,date:date||today(),endDate:date||today(),time:'09:00',endTime:'10:00',allDay:false,attendees:[],location:'',description:''};editDialog(id?'Edit event':'New event',field('Event title','title',e.title)+`<div class="field-grid"><div>${select('Event type','type',types.map(t=>`<option${t===e.type?' selected':''}>${t}</option>`).join(''))}</div><div>${select('Project','projectId',options(projects,e.projectId))}</div><div>${field('Start date','date',e.date,'date')}</div><div>${field('End date','endDate',e.endDate,'date')}</div></div><label class="inline-check"><input type="checkbox" name="allDay" id="wm-allDay"${e.allDay?' checked':''}> All-day event</label><div class="field-grid" id="event-times"><div>${field('Start time','time',e.time,'time')}</div><div>${field('End time','endTime',e.endTime,'time')}</div></div>`+field('Location or meeting link (optional)','location',e.location,'text',false)+area('Description','description',e.description)+checks('Attendees','attendees',members,e.attendees),async f=>{let v=Object.fromEntries(f);v.title=v.title.trim();v.allDay=f.has('allDay');v.attendees=f.getAll('attendees');v.cancelled=false;if(!v.title)throw Error('Enter an event title.');if(v.endDate<v.date||(!v.allDay&&v.endDate===v.date&&v.endTime<=v.time))throw Error('The event must end after it starts.');if(id)Object.assign(e,v);else events.push({...v,id:uid('event')});await commit('Event saved')},id?`<button type="button" class="danger-btn" data-event-cancel="${id}">Cancel event</button>`:'');let toggle=()=>{$('#event-times').classList.toggle('hidden',$('#wm-allDay').checked);$('#event-times').querySelectorAll('input').forEach(i=>i.required=!$('#wm-allDay').checked)};$('#wm-allDay').onchange=toggle;toggle()}
 function download(blob,name){let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 async function downloadDoc(id){let d=documents.find(d=>d.id===id),blob=d.kind==='note'?new Blob([d.content],{type:'text/plain'}):await read('files',id);if(!blob)throw Error('The file is not available in local storage.');download(blob,d.kind==='note'?d.name+'.txt':d.fileName)}
 async function previewDoc(id){let d=documents.find(d=>d.id===id);if(d.kind==='note'){editDialog(esc(d.name),`<pre class="document-preview">${esc(d.content||'This document is empty.')}</pre>`,async()=>modal.close());return;}let text='';if((['text/plain','text/markdown','application/json'].includes(d.mime)||/\.(txt|md|json)$/i.test(d.fileName))&&d.size<1048576){let file=await read('files',id);if(file)text=`<pre class="document-preview">${esc(await file.text())}</pre>`}editDialog(esc(d.name),`${text}<div class="file-preview"><span class="file-symbol">▤</span><p>${esc(d.fileName)}</p><p>${formatSize(d.size)} · ${esc(d.category)}</p><button type="button" class="secondary" data-doc-download="${id}">Download file</button><p>Download this file to open it in its native app.</p></div>`,async()=>modal.close())}
 async function backup(){await saveQueue;let files=[];for(let d of documents.filter(d=>d.kind==='file')){let file=await read('files',d.id);if(file)files.push({id:d.id,name:d.fileName,data:await fileData(file)})}download(new Blob([JSON.stringify({...snapshot(),files},null,2)],{type:'application/json'}),'workspace-backup-'+today()+'.json');toast('Backup exported, including files and avatars')}
 page.addEventListener('click',async e=>{let b=e.target.closest('button');if(!b)return;try{let a=b.dataset.action;if(a==='new-project')editProject();if(a==='new-doc')editDoc();if(a==='new-team')editTeam();if(a==='new-member')editMember();if(a==='new-event')editEvent();if(a==='backup')await backup();if(a==='toggle-trash'){trash=!trash;draw()}if(a==='today'){month=new Date().getMonth();year=new Date().getFullYear();draw()}if(b.dataset.projectEdit)editProject(b.dataset.projectEdit);if(b.dataset.teamEdit)editTeam(b.dataset.teamEdit);if(b.dataset.memberEdit)editMember(b.dataset.memberEdit);if(b.dataset.docEdit)editDoc(b.dataset.docEdit);if(b.dataset.docOpen)await previewDoc(b.dataset.docOpen);if(b.dataset.docDownload)await downloadDoc(b.dataset.docDownload);if(b.dataset.docTrash||b.dataset.docRestore){documents.find(d=>d.id===(b.dataset.docTrash||b.dataset.docRestore)).trashed=!!b.dataset.docTrash;await commit(b.dataset.docTrash?'Document moved to trash':'Document restored')}if(b.dataset.projectPlan){PlanningUI.show('wbs');PlanningUI.setProject(b.dataset.projectPlan)}if(b.dataset.projectDocs){selected=b.dataset.projectDocs;open('documents')}if(b.dataset.projectEvents){selected=b.dataset.projectEvents;open('calendar')}if(b.dataset.teamFocus){teamFocus=b.dataset.teamFocus;draw()}if(b.dataset.eventEdit)editEvent(b.dataset.eventEdit);if(b.dataset.eventDate)editEvent(null,b.dataset.eventDate);if(b.dataset.calendarMode){calendarMode=b.dataset.calendarMode;draw()}if(b.dataset.month){let d=new Date(year,month+Number(b.dataset.month),1);year=d.getFullYear();month=d.getMonth();draw()}}catch(error){toast(error.message)}});
 page.addEventListener('change',e=>{if(e.target.id==='work-project'){selected=e.target.value;draw()}if(e.target.id==='team-filter'){teamFocus=e.target.value;draw()}if(e.target.id==='event-type'){eventType=e.target.value;draw()}});
 page.addEventListener('input',e=>{if(e.target.id==='work-search'){let pos=e.target.selectionStart;search=e.target.value;draw();$('#work-search').focus();$('#work-search').setSelectionRange(pos,pos)}});
 modal.addEventListener('click',async e=>{if(e.target.closest('[data-close-work]'))modal.close();let b=e.target.closest('button');if(b?.dataset.docDownload){try{await downloadDoc(b.dataset.docDownload)}catch(error){$('#workspace-error').textContent=error.message}}if(b?.dataset.eventCancel){try{events.find(x=>x.id===b.dataset.eventCancel).cancelled=true;await commit('Event cancelled')}catch(error){$('#workspace-error').textContent=error.message}}});
 modal.addEventListener('submit',async e=>{e.preventDefault();let button=e.target.querySelector('[type=submit]');button.disabled=true;$('#workspace-error').textContent='';let before=structuredClone(snapshot());try{await submitAction(new FormData(e.target))}catch(error){({projects,issues,notes,milestones,activity,members,teams,documents,events}=before);$('#workspace-error').textContent=error.message}finally{button.disabled=false}});
 const createBefore=openCreate;openCreate=function(type){if(type==='project')editProject();else if(type==='milestone')editEvent(undefined,undefined,'Milestone');else createBefore(type)};
 document.addEventListener('click',e=>{let b=e.target.closest('[data-detail]');if(b){e.stopImmediatePropagation();selected=b.dataset.detail;open('projects')}},true);
 renderBefore();updateTeamSummary();
})();
